  const [rows,[meta]]=await serviceProbe(env,[[`SELECT value_json,revision FROM gsis_edge_records audit WHERE scope='roster' AND collection='audit' AND record_date=? AND record_id<>'$' AND ${visible} ORDER BY position,record_id`,[date]],["SELECT json_extract(value_json,'$.value') revision FROM gsis_edge_records WHERE scope='roster' AND collection='revision' AND record_id='$'"]]);
