async function calendarStatisticsSnapshot(env,guard){if(guard)await guard();const response=await fetch(env.CALENDAR_APPS_SCRIPT_URL,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'rosterStatisticsCalendar',payload:{year:Number(edgeRosterClock().today.slice(0,4))},service:'gsis-roster-notifier-v1',proxySecret:gsisApiSecret(env,'CALENDAR_PROXY_SECRET'),requestId:crypto.randomUUID()}),signal:AbortSignal.timeout(20000),redirect:'follow'}),envelope=await response.json(),value=envelope.result||envelope.data;if(!envelope.ok||!Array.isArray(value?.terms)||!Array.isArray(value?.semesters))fail(503,'ROSTER_CALENDAR_STATISTICS','Calendar term boundaries are unavailable.');return value;}
async function processEdgeInstructionDrafts(env){const jobs=await pendingServiceRows(env,'edgeInstructionDrafts');let applied=0,needsReview=0;for(const draft of jobs){try{await mutateEdgeRoster(env,{actor:draft.actor,who:draft.identity,requestId:'instructions-'+draft.id+(draft.retryCount?'-'+draft.retryCount:''),allowDuringQuiesce:true,command:{operation:'saveInstructions',date:draft.date,absenceIds:draft.savedIds},apply(state,ctx){const job=state.edgeInstructionDrafts.find(row=>row.id===draft.id);if(job.status!=='pending')return {replayed:true};for(const id of job.savedIds){const absence=state.absences.find(row=>row.id===id&&!row.deletedAt);if(!absence)fail(409,'ABSENCE_CHANGED','The absence changed before its instructions could be applied.');const notes=(job.command.instructionsByStaffDate?.[absence.staffId]||job.command.instructionsByDate)?.[absence.date];if(notes===undefined)continue;const expected=job.command.expectedInstructionScopes?.[absence.date],day=ctx.days[absence.date];if(expected&&(expected.timetableId!==day?.id||expected.parity!==day?.parity))fail(409,'INSTRUCTION_SOURCE_CHANGED','The lesson source changed. Review the retained instructions.');GSISRosterOperations.apply(state,ctx,{operation:'saveInstructions',date:absence.date,absenceId:id,instructions:notes,instructionsNA:job.command.instructionsNA===true});}job.status='applied';job.appliedAt=ctx.iso;return {savedIds:job.savedIds};}});applied++;}catch(error){if(!error.status||[400,403,404,409,422].includes(error.status)&&!['EDGE_CONFLICT','ROSTER_COMMIT_BUSY'].includes(error.code)){await mutateEdgeRoster(env,{actor:'roster-service',requestId:'instructions-review-'+draft.id+(draft.retryCount?'-'+draft.retryCount:''),allowDuringQuiesce:true,command:{operation:'instructionReview'},needsContext:false,apply(state,ctx){const row=state.edgeInstructionDrafts.find(row=>row.id===draft.id);if(row?.status==='pending')Object.assign(row,{status:'needsReview',reasonCode:error.code||'INSTRUCTIONS_NEED_REVIEW',message:error.status?error.message:'The absence is saved. Review the retained relief instructions.',reviewAt:ctx.iso});return {retained:true};}});needsReview++;}}}return {applied,needsReview,pending:jobs.length-applied-needsReview};}

function personalCompletion(state,staffId,today,now=Date.now()){return GSISRosterAllocation.personalCompletion(state,staffId,today,now);}

function hasInstructionDraft(value){if(value===undefined)return false;if(!value||typeof value!=='object'||Array.isArray(value))return true;return Object.values(value).some(row=>typeof row==='string'?row.trim().length>0:hasInstructionDraft(row));}

function recordOnly(p){return ['previewStaplerMigration','migrateStaplerPlans','previewTimetableReconcile','confirmTimetableReconcile'].includes(p.operation)||p.operation==='read'&&['timetableReview','staplerMigration','timetableReconcile'].includes(p.view)||['publish','dailyNotify','notifyDaily','createStapler','importStapler'].includes(p.operation)||simpleOps.has(p.operation)||['saveCustomInstruction','deleteCustomInstruction','setCustomInstructionEnabled','systemConfig','saveSystemConfig','nameBridges','saveNameBridge','deleteNameBridge','sendDailyEmploymentReport'].includes(p.operation)||p.operation==='read'&&(['reportForm','schoolAbsences','teacherDailyUpdate','dailyNotify','mine','duties','prune','notificationReadiness','dutyRoster','systemConfig','nameBridges','dailyEmployment','staplerDates','custom','intake','currentDuty'].includes(p.view)||p.compact===true&&['report','entry'].includes(p.view));}
function reconcileOperationalState(state,ctx,readTriggered=false){
 return GSISRosterOperations.reconcileOperational(state,ctx,readTriggered);
}

export async function readRosterMirrorStatus(env){
 let fresh;try{fresh=await freshRosterMetadata(env);}catch(error){if(error.code!=='ROSTER_EDGE_NOT_ACTIVE')throw error;return {enabled:false,available:false,mode:'legacy',lagMs:0,lagMinutes:0,warning:error.message};}if(fresh){
  const source=database(env),db=source.withSession?.('first-primary')||source,result=await db.prepare("SELECT h.scope,h.revision,c.phase FROM gsis_edge_heads h CROSS JOIN gsis_roster_mirror_control c WHERE h.scope IN ('roster','roster-register') AND c.id=1").all(),rows=result?.results;
  if(result?.success===false||!Array.isArray(rows)||rows.length!==2||new Set(rows.map(row=>row.scope)).size!==2||rows.some(row=>!Number.isSafeInteger(row.revision)||!['normal','quiescing','paused','released'].includes(row.phase)))fail(503,'ROSTER_FRESH_START_PROOF','The fresh Roster archive status could not be verified.');
  const phase=rows[0].phase;return {enabled:false,canRelease:phase!=='released',archiveOnly:true,phase,archiveId:fresh.archiveId,revisions:Object.fromEntries(rows.map(row=>[row.scope==='roster'?'roster':'register',row.revision])),pending:0,lagMs:0,warning:''};
 }
 const status=await rosterMirrorStatus(env);if(!status.enabled)return status;
 const db=database(env),rows=await db.prepare("SELECT record_id,value_json FROM gsis_edge_records WHERE scope='roster' AND collection='systemConfig' AND record_id='key:googleBackupLagMinutes'").all();
 const configured=rows.results?.[0]?JSON.parse(rows.results[0].value_json):10,threshold=Number.isInteger(configured)&&configured>=1&&configured<=120?configured:10;
 const now=Date.now(),sg=new Date(now+28800000),minute=sg.getUTCHours()*60+sg.getUTCMinutes(),schoolHours=sg.getUTCDay()>0&&sg.getUTCDay()<6&&minute>=420&&minute<840;
 return {...status,pending:status.pendingCount||0,progress:status.pending,mirroredRevisions:status.latest?.revisions||null,largestPart:typeof status.latest?.proof?.largestPart==='number'?{name:'Largest backup part',chars:status.latest.proof.largestPart}:status.latest?.proof?.largestPart||null,lagThresholdMinutes:threshold,behindThreshold:schoolHours&&status.lagMs>threshold*60000,warning:schoolHours&&status.lagMs>threshold*60000?'Google backup is behind the configured threshold.':''};
}
export async function mirrorEdgeRoster(env,options={}){if(edgeRosterEnabled(env)&&await freshRosterMetadata(env))return {enabled:false,archiveOnly:true,skipped:true,reason:'google-frozen-archive'};return runRosterMirror(env,{bridge:p=>signedBridge(env,p),...options});}
async function rosterMirrorQuiescent(env){
 const db=database(env),control=await db.prepare('SELECT phase FROM gsis_roster_mirror_control WHERE id=1').first();if(['paused','released'].includes(control?.phase))return true;
 const records=await db.prepare("SELECT COUNT(*) n FROM gsis_edge_records WHERE scope='roster' AND record_id<>'$' AND ((collection IN ('outbox','inboxMessages','inboxAlerts','peerMail','dailyEmploymentMail') AND json_extract(value_json,'$.status') IN ('claimed','sending')) OR (collection IN ('edgePeerProposals','edgeInstructionDrafts') AND json_extract(value_json,'$.status') IN ('pending','needsReview')) OR (collection='edgeAllocatorRuns' AND json_extract(value_json,'$.state') IN ('running','committing')))").first();
 if(records.n)return false;
 const exists=await db.prepare("SELECT 1 ok FROM sqlite_master WHERE type='table' AND name='gsis_absence_transport'").first();if(!exists)return true;
 const transport=await db.prepare("SELECT COUNT(*) n FROM gsis_absence_transport WHERE state NOT IN ('forwarded','withdrawn')").first();return transport.n===0;
}

// Output work is entered only by the notification Worker timer/queue.
export async function driveOutputsEdgeRoster(env,options={}){
 return runBackupJobs(env,{...options,bridge:p=>signedBridge(env,p),continuity:async now=>{
  const refs=await readEdgeRosterReferences(env),today=edgeRosterClock(now).today,dates=[today];
  for(let n=1;n<=366&&dates.length<6;n++){const date=GSISRosterAllocation.addDays(today,n),day=refs.calendarByDate?.[date];if(day?.available!==true)fail(503,'BACKUP_CALENDAR','Verified school dates are required for the continuity Sheet.');if(day.schoolDay)dates.push(date);}
  if(dates.length!==6)fail(503,'BACKUP_CALENDAR','The next five school days are unavailable.');
  const loaded=await loadEdgeRoster(env,{hydrate:true,dates}),ctx=await buildEdgeRosterContext(env,loaded.state,{operation:'exportDaily',fullTeachers:true,dates});
  return buildContinuityView(loaded.state,ctx,dates);
 },alert:health=>queueDriveOutputAlert(env,health)});
}
async function queueDriveOutputAlert(env,health){
  if(!health.warnings.length)return {queued:false};if(GSISRosterAllocation.schedule(Date.now()).quiet||env.WHATSAPP_ENABLED!=='true')return {queued:false};
  const fingerprint=sha256Hex(JSON.stringify(health.warnings)),message='Roster Drive outputs need Admin attention: '+health.warnings.join(', ')+'. Open System Health and the backup ledger.';
  try{return await mutateEdgeRoster(env,{actor:'roster-service',requestId:'backup-alert-'+health.alertId,command:{operation:'currentDuty'},domainChanged:false,apply(state,ctx){const key='drive-backup:'+health.alertId;GSISRosterOperations.smcAlert(state,ctx,ctx.today,key,message,true);const duty=GSISRosterOperations.dutySMC(state,ctx,ctx.today);for(const id of (ctx.adminIds||[]).filter(id=>!duty.includes(id)&&ctx.people.some(p=>p.id===id&&p.active&&/^[1-9]\d{7,14}$/.test(GSISRosterOperations.mobile(p.mobile)))))GSISRosterOperations.queue(state,ctx,'smc_alert',id,ctx.today,{summary:message,audience:'backup-admin',templateKey:'smc_attention'},null,key+':'+id);if(!state.outbox.some(j=>j.key?.startsWith(key+':')))throw Object.assign(Error('Backup alert is awaiting a recipient.'),{code:'BACKUP_ALERT_PENDING'});return {queued:true,alertRecorded:true};}});}catch(error){if(error.code==='BACKUP_ALERT_PENDING')return {queued:false};throw error;}
}

export async function driveBackupAdmin(env,input,who){
 if(!edgeRosterEnabled(env))fail(409,'BACKUP_AUTHORITY','D1 must own Roster before using its backup ledger.');
 const refs=await readEdgeRosterReferences(env),contacts=actorContacts(refs,who);if(contacts.user.rosterAdmin!==true)fail(403,'ROSTER_ADMIN_REQUIRED','Current Admin access is required.');
 if(input.operation==='read')return {status:await backupStatus(database(env)),config:await readBackupConfig(database(env)),rows:await backupLedger(database(env),input.filters||{}),requests:await backupRequests(database(env))};
 if(['verify','restore'].includes(input.operation))return queueBackupRequest(database(env),{id:input.requestId,kind:input.operation,manifestFileId:input.manifestFileId,retry:input.retry===true,actor:who.email});
 fail(400,'BACKUP_OPERATION','Choose a supported backup action.');
}


// Existing Allocation Audit TXT and the daily workbook share one captured revision.
export async function dailyOutputsEdgeRoster(env,options={}){
 return runDailyOutputs(env,{...options,bridge:p=>signedBridge(env,p),quiet:async()=> (await readQuietMode(database(env))).active||(await auditAvailability(env)).notifications,alert:health=>queueDriveOutputAlert(env,health),seed:async today=>{
  const db=database(env);if(await db.prepare('SELECT 1 found FROM gsis_roster_daily_outputs WHERE date=?').bind(today).first())return;
  const refs=await readEdgeRosterReferences(env);if(refs.calendarByDate?.[today]?.available!==true||refs.calendarByDate[today].schoolDay!==true)return;
  const register=await readEdgeRosterRegister(env),plan=await db.prepare("SELECT 1 found FROM gsis_edge_records WHERE scope='roster' AND collection='staplerPlans' AND record_date=? AND (json_extract(value_json,'$.confirmedRevision') IS NOT NULL OR json_extract(value_json,'$.publishedRevision') IS NOT NULL)").bind(today).first();
  if(!GSISRoster.active(register.state.entries,today)&&!plan)return;
  await db.prepare("INSERT OR IGNORE INTO gsis_roster_daily_outputs(date,desired_revision) SELECT ?,revision FROM gsis_edge_heads WHERE scope='roster' AND mode='active'").bind(today).run();
 },prepare:async(date,{now,final})=>{
  const refs=await readEdgeRosterReferences(env),calendar=refs.calendarByDate?.[date];if(calendar?.available!==true)fail(503,'DAILY_OUTPUT_CALENDAR','The school date is not verified.');if(calendar.schoolDay!==true)return {schoolDay:false};
  const loaded=await loadEdgeRoster(env,{hydrate:true,dates:[date]}),state=loaded.state,ctx=await buildEdgeRosterContext(env,state,{operation:'exportDaily',date,fullTeachers:true,dailyDrive:true});
  const originalCount=state.audit.filter(r=>r.date===date&&!r.auditExportSuppressed||r.date===date&&r.essential).length;
  await auditSchema(env);const previous=await database(env).prepare('SELECT reference_json FROM gsis_roster_audit_exports WHERE date=?').bind(date).first(),reference=state.allocationAuditExports?.[date]?.archiveObject||(previous?JSON.parse(previous.reference_json):null);
  if(reference){const old=await objectRead(env,reference);if(old.date!==date||!Array.isArray(old.audit))fail(503,'DAILY_OUTPUT_AUDIT','The retained audit evidence could not be verified.');for(const collection of ['audit','optimisationRuns']){const merged=new Map((old[collection]||[]).map(r=>[r.id,r]));for(const row of state[collection].filter(r=>r.date===date)){const prior=merged.get(row.id);merged.set(row.id,row.archiveRef&&prior?prior:{...prior,...row,...(!row.decisionEvidence&&prior?.decisionEvidence?{decisionEvidence:prior.decisionEvidence}:{})});}state[collection]=state[collection].filter(r=>r.date!==date).concat([...merged.values()]);}}
  if([...state.audit,...state.optimisationRuns].some(r=>r.date===date&&(r.archiveRef||r.decisionEvidenceArchive&&!r.decisionEvidence)))fail(503,'DAILY_OUTPUT_AUDIT_ARCHIVE','Original audit evidence is unavailable; the full trail was not truncated.');
  await hydrateAuditEvidence(state,[date],{all:true});rosterAllocationAuditCapture_(state);
  const daily=await sanitizeBackup(GSISRosterOperations.read(state,{...ctx,iso:new Date(now).toISOString()},{operation:'exportDaily',date,fullTeachers:true,dailyDrive:true}));daily.timetableName=daily.teacherSummary.staplerStatus==='baseline'?(ctx.timetableEntries.find(e=>e.id===ctx.days[date]?.id)?.name||'Baseline timetable'):'Stapler plan';
  const page=RosterExport.dailyTeacherPage(daily,{final}),book=RosterExport.workbookFiles([page]),bytes=new Uint8Array(await GSISExcel.packageFiles(book.files).arrayBuffer()),text=rosterAllocationAuditText_(state,date,new Date(now).toISOString());
  const guards=[{scope:'roster',revision:loaded.revision,mode:'active'},...ctx.edgeGuards],checks=await database(env).batch([...guards.map(g=>database(env).prepare('SELECT revision,mode FROM gsis_edge_heads WHERE scope=?').bind(g.scope)),database(env).prepare("SELECT COALESCE(MAX(revision),0) revision FROM gsis_edge_records WHERE scope='roster' AND collection='audit' AND record_date=? AND record_id<>'$'").bind(date)]);
  if(guards.some((g,i)=>checks[i].results?.[0]?.revision!==g.revision||checks[i].results?.[0]?.mode!==g.mode))return {deferred:'source-advanced'};
  const audit=checks.at(-1).results[0];
  const evidence=text?await objectWrite(env,'audit',date,{schema:1,date,revision:state.revision,audit:state.audit.filter(r=>r.date===date),optimisationRuns:state.optimisationRuns.filter(r=>r.date===date)}):null;
  return {schoolDay:true,revision:state.revision,sourceRevision:loaded.revision,metadata:{auditReference:evidence,sourceCount:originalCount,sourceRevision:audit.revision},files:[{kind:'excel',bytes,records:page.rows.filter(r=>r.teacherId&&r.field===0).length},...(text?[{kind:'log',bytes:new TextEncoder().encode(text),records:state.audit.filter(r=>r.date===date).length+state.optimisationRuns.filter(r=>r.date===date).length}]:[])]};
 },onComplete:async pending=>{const m=pending.metadata;if(!m?.auditReference||!pending.files.some(f=>f.kind==='log'&&f.done&&!f.alreadyFinal))return;await auditSchema(env);await database(env).prepare('INSERT INTO gsis_roster_audit_exports(date,source_count,source_revision,reference_json,exported_at) VALUES(?,?,?,?,?) ON CONFLICT(date) DO UPDATE SET source_count=excluded.source_count,source_revision=excluded.source_revision,reference_json=excluded.reference_json,exported_at=excluded.exported_at WHERE source_revision<=excluded.source_revision').bind(pending.date,m.sourceCount,m.sourceRevision,JSON.stringify(m.auditReference),Date.now()).run();}});
}
